import math


def thin_points(points, minimum):
    if isinstance(minimum, bool) or not isinstance(minimum, (int, float)):
        raise TypeError("minimum must be numeric")
    if not math.isfinite(minimum) or minimum < 0:
        raise ValueError("minimum must be finite and non-negative")
    try:
        raw = list(points)
    except TypeError:
        raise TypeError("points must be iterable") from None
    checked = []
    for point in raw:
        try:
            pair = list(point)
        except TypeError:
            raise TypeError("each point must be iterable") from None
        if len(pair) != 2:
            raise ValueError("each point must have two coordinates")
        if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in pair):
            raise TypeError("coordinates must be numeric")
        if any(not math.isfinite(v) for v in pair):
            raise ValueError("coordinates must be finite")
        checked.append((float(pair[0]), float(pair[1])))
    kept = []
    for point in checked:
        if all(math.dist(point, other) > minimum for other in kept):
            kept.append(point)
    return kept
